import Foundation
import Hummingbird
import HummingbirdWebSocket
import Logging
import NIOConcurrencyHelpers
import NIOCore
import NIOWebSocket
import Petrel
import PetrelFirehose
import SwanSQLite
import Synchronization

/// A non-sensitive, structured lifecycle observation for one public
/// `subscribeRepos` WebSocket. The connection identifier is generated by Swan
/// and is meaningful only for pairing the open and close records in local lab
/// logs; no request, header, token, peer, or event value is retained.
public struct PublicFirehoseSubscriptionObservation: Sendable, Equatable {
  public enum Event: String, Sendable {
    case opened = "swan.public_firehose.subscribe_repos.open"
    case closed = "swan.public_firehose.subscribe_repos.close"
  }

  public enum CursorMode: String, Sendable {
    case live
    case fullWindow = "full_window"
    case backfill
  }

  public enum CloseCategory: String, Sendable {
    case completed
    case failure
    case cancellation
  }

  public enum CloseReason: String, Sendable {
    case clientClosed = "client_closed"
    case serverShutdown = "server_shutdown"
    case futureCursor = "future_cursor"
    case cursorResolutionFailed = "cursor_resolution_failed"
    case inboundDrainFailed = "inbound_drain_failed"
    case consumerTooSlow = "consumer_too_slow"
    case tailerFailed = "tailer_failed"
    /// The subscriber reservation was full: the upgrade completed but no
    /// subscription was started. Local diagnostics only — the wire carries a
    /// WebSocket close code, never this name.
    case subscriberCapacity = "subscriber_capacity"
  }

  public let event: Event
  public let connectionID: String
  public let cursorMode: CursorMode?
  public let cursorValue: Int64?
  public let closeCategory: CloseCategory?
  public let closeReason: CloseReason?

  fileprivate static func opened(
    connectionID: String,
    cursor: Int64?
  ) -> Self {
    let mode: CursorMode
    switch cursor {
    case nil: mode = .live
    case 0: mode = .fullWindow
    default: mode = .backfill
    }
    return Self(
      event: .opened,
      connectionID: connectionID,
      cursorMode: mode,
      cursorValue: cursor,
      closeCategory: nil,
      closeReason: nil
    )
  }

  fileprivate static func closed(
    connectionID: String,
    category: CloseCategory,
    reason: CloseReason
  ) -> Self {
    Self(
      event: .closed,
      connectionID: connectionID,
      cursorMode: nil,
      cursorValue: nil,
      closeCategory: category,
      closeReason: reason
    )
  }

  /// The suppression key for this record, and the whole point of F33.
  ///
  /// It deliberately excludes ``connectionID``. That field is a fresh UUID per
  /// socket, so keying on it would make every record distinct from every other
  /// record and the throttle a no-op — which is exactly the shape that let
  /// anonymous connect/disconnect churn set the journal's growth rate. What
  /// the line actually carries is (which event, which shape of it), and
  /// repeating that pair adds nothing.
  ///
  /// The key space is bounded by construction: three cursor modes for an open,
  /// and the close categories crossed with the close reasons for a close.
  var diagnosticKey: String {
    if let closeCategory, let closeReason {
      return "\(closeCategory.rawValue)|\(closeReason.rawValue)"
    }
    return cursorMode?.rawValue ?? "none"
  }

  fileprivate func log(to logger: Logger) {
    guard let suppressed = publicFirehoseDiagnosticThrottle.admit(
      method: event.rawValue,
      reason: diagnosticKey
    ) else {
      return
    }
    var metadata: Logger.Metadata = [
      "event": .string(event.rawValue),
      "connection_id": .string(connectionID),
    ]
    if let cursorMode {
      metadata["cursor_mode"] = .string(cursorMode.rawValue)
      metadata["cursor_value"] = .string(cursorValue.map(String.init) ?? "none")
    }
    if let closeCategory, let closeReason {
      metadata["close_category"] = .string(closeCategory.rawValue)
      metadata["close_reason"] = .string(closeReason.rawValue)
    }
    if suppressed > 0 {
      metadata["suppressed_repeats"] = .string(String(suppressed))
    }
    publicFirehoseDiagnosticJournalLines.withLock { $0 += 1 }
    logger.info(Logger.Message(stringLiteral: event.rawValue), metadata: metadata)
  }
}

/// The firehose's **own** journal window, deliberately not the instance the
/// public read routes use (`publicReadDiagnosticThrottle`,
/// `SwanPublicRepositoryReadXRPC.swift:1468`). Sharing one would let anonymous
/// subscribe churn spend the suppression budget that makes a real public-read
/// refusal visible, and vice versa.
///
/// One second matches the sibling: long enough that a saturating anonymous
/// caller cannot push line rate past one per second per distinct record shape,
/// short enough that an operator watching a live incident still sees it
/// reappear at a readable cadence.
let publicFirehoseDiagnosticThrottle = PublicReadDiagnosticThrottle(
  window: .seconds(1)
)

/// Test seam: subscription lifecycle lines this module has written. Never read
/// by production code — it exists so a test can assert that journal volume
/// stops tracking connection churn, which is invisible from the wire.
let publicFirehoseDiagnosticJournalLines = Mutex(0)

/// The durable runtime backing the public `com.atproto.sync.subscribeRepos`
/// WebSocket endpoint. Constructed once at startup and shared by every
/// connection; per-connection state lives entirely inside the upgrade handler.
public struct SwanPublicFirehoseStreamingRuntime: Sendable {
  public let database: SQLiteFirehoseDatabase
  public let hub: PublicFirehoseWakeupHub
  public let limits: PublicFirehoseStreamingLimits
  public let logger: Logger
  public let observeSubscription:
    @Sendable (PublicFirehoseSubscriptionObservation) async -> Void

  public init(
    database: SQLiteFirehoseDatabase,
    hub: PublicFirehoseWakeupHub,
    limits: PublicFirehoseStreamingLimits,
    logger: Logger,
    observeSubscription: (
      @Sendable (PublicFirehoseSubscriptionObservation) async -> Void
    )? = nil
  ) {
    self.database = database
    self.hub = hub
    self.limits = limits
    self.logger = logger
    if let observeSubscription {
      self.observeSubscription = observeSubscription
    } else {
      self.observeSubscription = { observation in
        observation.log(to: logger)
      }
    }
  }
}

/// Registers the `subscribeRepos` WebSocket route on the public router.
///
/// Upgrade requests are gated on the `Upgrade: websocket` header and a strict
/// single-`cursor` query (D7): any malformed cursor rejects the upgrade.
/// Non-upgrade GETs to the exact path receive 405 from the route itself.
public func registerPublicFirehoseStreamingEndpoint(
  on router: Router<SwanHTTPRequestContext>,
  runtime: SwanPublicFirehoseStreamingRuntime,
  admission: PublicFirehoseSubscriberAdmission
) {
  router.ws(
    "/xrpc/com.atproto.sync.subscribeRepos",
    shouldUpgrade: { request, _ in
      switch publicFirehoseUpgradeDecision(request) {
      case .upgrade:
        return .upgrade([:])
      case .reject:
        return .dontUpgrade
      }
    },
    onUpgrade: { inbound, outbound, context in
      await publicFirehoseOnUpgrade(
        inbound: inbound,
        outbound: outbound,
        context: context,
        runtime: runtime,
        admission: admission
      )
    }
  )
}

// MARK: - Upgrade decision

private enum PublicFirehoseUpgradeDecision {
  case upgrade(cursor: Int64?)
  case reject
}

/// Strict cursor policy per D7, mirroring the house strict-query style:
/// no fragments, query bounded at 8 KiB, at most one `cursor` key, value
/// strictly decimal (digits only, non-empty) and at or below the firehose
/// sequence ceiling. Anything else rejects the upgrade.
private func publicFirehoseUpgradeDecision(
  _ request: Request
) -> PublicFirehoseUpgradeDecision {
  guard request.headers[.upgrade] == "websocket" else {
    return .reject
  }
  guard !request.uri.string.contains("#") else {
    return .reject
  }
  guard let query = request.uri.query else {
    // No query: no cursor, stream live.
    return .upgrade(cursor: nil)
  }
  guard query.utf8.count <= 8 * 1_024 else {
    return .reject
  }
  if query.isEmpty {
    return .upgrade(cursor: nil)
  }
  var cursorSeen = false
  var cursor: Int64?
  for segment in query.split(separator: "&", omittingEmptySubsequences: false) {
    let pair = segment.split(
      separator: "=", maxSplits: 1, omittingEmptySubsequences: false
    )
    guard pair.count == 2, pair[0] == "cursor", !cursorSeen,
          let parsed = strictFirehoseCursor(pair[1]) else {
      return .reject
    }
    cursor = parsed
    cursorSeen = true
  }
  return .upgrade(cursor: cursor)
}

private func strictFirehoseCursor(_ value: Substring) -> Int64? {
  guard !value.isEmpty,
        value.utf8.allSatisfy({ $0 >= UInt8(ascii: "0") && $0 <= UInt8(ascii: "9") })
  else {
    return nil
  }
  var result: Int64 = 0
  for byte in value.utf8 {
    let digit = Int64(byte - UInt8(ascii: "0"))
    let (multiplied, multiplicationOverflow) =
      result.multipliedReportingOverflow(by: 10)
    let (added, additionOverflow) = multiplied.addingReportingOverflow(digit)
    if multiplicationOverflow || additionOverflow
      || added > FirehoseFrameLimits.maximumSequence {
      return nil
    }
    result = added
  }
  return result
}

// MARK: - Upgrade handler

/// RFC 6455 close code 1013, "Try Again Later". NIO names codes 1000-1011 and
/// reports the rest as `.unknown`; the number is what goes on the wire.
private let publicFirehoseCapacityRefusalCode = WebSocketErrorCode.unknown(1_013)

/// Per-connection streaming session. Resolves the cursor policy, then runs
/// two sibling tasks — an inbound drain that consumes client close/ping
/// frames and the tailer loop fed by the hub — and cancels the sibling when
/// either ends. The subscription is finished before exit because a suspended
/// `AsyncStream.next()` is not resumed by cancellation alone.
///
/// Admission is charged here rather than in `shouldUpgrade` because this is
/// the only scope with a release site: the upgraded channel holds its listener
/// slot until it closes, so the lease must live exactly as long as the handler.
private func publicFirehoseOnUpgrade(
  inbound: WebSocketInboundStream,
  outbound: WebSocketOutboundWriter,
  context: WebSocketRouterContext<SwanHTTPRequestContext>,
  runtime: SwanPublicFirehoseStreamingRuntime,
  admission: PublicFirehoseSubscriberAdmission
) async {
  let logger = context.logger
  // Charged before any per-connection work — before the cursor reads, the hub
  // subscription, and the two long-lived tasks — and released exactly once on
  // every exit. This is the only release site: `shouldUpgrade` has none, and
  // its `.dontUpgrade` hard-codes 405
  // (`hummingbird-websocket/Sources/HummingbirdWebSocket/WebSocketRouter.swift:92-93`),
  // which is the wrong answer for a capacity refusal anyway.
  let lease = admission.reserve()
  defer { lease?.release() }
  // `shouldUpgrade` already validated the request; re-parsing the same
  // request here is deterministic and avoids carrying per-request state in
  // the shared runtime.
  let cursor: Int64?
  switch publicFirehoseUpgradeDecision(context.request) {
  case .upgrade(let parsed): cursor = parsed
  case .reject: cursor = nil
  }
  let connectionID = UUID().uuidString.lowercased()
  await runtime.observeSubscription(.opened(
    connectionID: connectionID,
    cursor: cursor
  ))
  guard lease != nil else {
    // 1013 "Try Again Later" — a retryable, transport-level refusal. The
    // alternative, a new `#error` name in the subscribeRepos error set, is
    // lexicon-visible: the schema defines only `FutureCursor` and
    // `ConsumerTooSlow`, and a relay meeting an unknown name may treat it as
    // fatal rather than as backpressure. No reason string, so nothing about
    // Swan's capacity is disclosed to an anonymous caller.
    try? await outbound.close(publicFirehoseCapacityRefusalCode, reason: nil)
    await runtime.observeSubscription(.closed(
      connectionID: connectionID,
      category: .failure,
      reason: .subscriberCapacity
    ))
    return
  }

  let lastSent: Int64
  do {
    let maxSequencedSeq = try await runtime.database.maxSequencedSeq()
    let retainedFromSeq = try await runtime.database.retainedFromSeq()
    switch PublicFirehoseCursorPolicy.resolve(
      cursor: cursor,
      maxSequencedSeq: maxSequencedSeq,
      retainedFromSeq: retainedFromSeq
    ) {
    case .futureCursor:
      try? await outbound.write(
        .binary(ByteBuffer(data: try FirehoseFrameEncoder.errorFrame(error: "FutureCursor", message: nil)))
      )
      try? await outbound.close(.normalClosure, reason: "FutureCursor")
      await runtime.observeSubscription(.closed(
        connectionID: connectionID,
        category: .failure,
        reason: .futureCursor
      ))
      return
    case .outdatedCursor:
      try? await outbound.write(
        .binary(ByteBuffer(data: try FirehoseFrameEncoder.infoFrame(name: "OutdatedCursor", message: nil)))
      )
      // Stream from the oldest retained event. `retainedFromSeq` is always
      // non-nil here (the policy only reports `.outdatedCursor` against one);
      // the defensive fallback keeps the cursor at the window start.
      lastSent = (retainedFromSeq ?? 1) - 1
    case .live:
      lastSent = maxSequencedSeq
    case .fullWindow:
      // Start just before the oldest retained row (not literal 0) so the
      // slow-consumer sequence-lag check is computed against what is
      // actually deliverable, not against sequences retention already
      // deleted. This preserves the design rule that `cursor=0` streams the
      // retained window without an `OutdatedCursor` info frame.
      lastSent = max(0, (retainedFromSeq ?? 1) - 1)
    case .backfill(from: let from):
      lastSent = from
    }
  } catch {
    logger.error("public firehose cursor resolution failed")
    try? await outbound.close(.unexpectedServerError, reason: nil)
    await runtime.observeSubscription(.closed(
      connectionID: connectionID,
      category: .failure,
      reason: .cursorResolutionFailed
    ))
    return
  }

  let (wakeupStream, finishWakeup) = await runtime.hub.subscribeWithFinish()
  // One long-lived task per connection forwards hub bumps into an atomic
  // mailbox. `waitForWakeup` reads the mailbox without ever blocking, so a
  // bump that arrived before the subscriber registered (or a lost signal)
  // always falls back to the tailer's bounded idle poll; a suspended
  // `AsyncStream.next()` inside this task is resumed by `finishWakeup()`
  // before the group scope exits.
  let wakeupMailbox = NIOLockedValueBox<Int64?>(nil)
  Task {
    for await seq in wakeupStream {
      wakeupMailbox.withLockedValue { $0 = seq }
    }
  }
  let tailer = PublicFirehoseTailer(
    database: runtime.database,
    limits: runtime.limits,
    logger: logger
  )
  let disposition = await withTaskGroup(
    of: PublicFirehoseSubscriptionDisposition.self
  ) { group in
    group.addTask {
      // Draining the inbound stream keeps the library processing control
      // frames (close/ping) for the lifetime of the connection. This task
      // ends when the client closes or the channel tears down.
      do {
        for try await _ in inbound {}
        if Task.isCancelled {
          return .cancellation
        }
        return .completed(.clientClosed)
      } catch {
        if Task.isCancelled || error is CancellationError {
          return .cancellation
        }
        logger.debug("public firehose inbound drain failed")
        return .failure(.inboundDrainFailed)
      }
    }
    group.addTask {
      return await publicFirehoseRunTailer(
        tailer: tailer,
        initialLastSent: lastSent,
        outbound: outbound,
        wakeupMailbox: wakeupMailbox,
        logger: logger
      )
    }
    // Wait for whichever child ends first, then cancel the sibling and
    // finish the hub subscription so the wakeup forwarder's suspended
    // `AsyncStream.next()` resumes instead of leaking the subscriber.
    let first = await group.next() ?? .cancellation
    group.cancelAll()
    finishWakeup()
    return first
  }
  let finalDisposition: PublicFirehoseSubscriptionDisposition =
    Task.isCancelled ? .cancellation : disposition
  await runtime.observeSubscription(.closed(
    connectionID: connectionID,
    category: finalDisposition.category,
    reason: finalDisposition.reason
  ))
}

private enum PublicFirehoseSubscriptionDisposition: Sendable {
  case completed(PublicFirehoseSubscriptionObservation.CloseReason)
  case failure(PublicFirehoseSubscriptionObservation.CloseReason)
  case cancellation

  var category: PublicFirehoseSubscriptionObservation.CloseCategory {
    switch self {
    case .completed: .completed
    case .failure: .failure
    case .cancellation: .cancellation
    }
  }

  var reason: PublicFirehoseSubscriptionObservation.CloseReason {
    switch self {
    case .completed(let reason), .failure(let reason): reason
    case .cancellation: .serverShutdown
    }
  }
}

/// Runs the tailer loop for a connection, restarting it in place after a
/// retention advance so the session survives instead of closing.
///
/// `PublicFirehoseTailerError.outdatedCursor` writes an `#info`
/// `OutdatedCursor` frame and re-enters `tailer.run` from the new retained
/// boundary — the cursor is mutable across iterations for exactly this
/// resume. `consumerTooSlow`/`writeTooSlow` map to a `ConsumerTooSlow` error
/// frame followed by a close, ending the loop. Any other failure (closed
/// channel, database error) ends the loop without a control frame; the
/// sibling task group teardown handles the channel.
private func publicFirehoseRunTailer(
  tailer: PublicFirehoseTailer,
  initialLastSent: Int64,
  outbound: WebSocketOutboundWriter,
  wakeupMailbox: NIOLockedValueBox<Int64?>,
  logger: Logger
) async -> PublicFirehoseSubscriptionDisposition {
  // `@Sendable` because the tailer races every write against its deadline in
  // a task group; `WebSocketOutboundWriter` is itself `Sendable`.
  let outboundWrite: @Sendable (Data) async throws -> Void = { frameBytes in
    try await outbound.write(.binary(ByteBuffer(data: frameBytes)))
  }
  let wakeupRead: @Sendable () async -> Int64? = {
    // Never blocks: consumes the newest pending bump or reports none, so the
    // tailer falls back to its own bounded idle poll (the recovery path for
    // a missed or pre-subscription wakeup, and for a lost retention signal).
    wakeupMailbox.withLockedValue { value in
      let pending = value
      value = nil
      return pending
    }
  }

  var lastSent = initialLastSent
  while !Task.isCancelled {
    do {
      try await tailer.run(
        lastSent: lastSent,
        outbound: outboundWrite,
        waitForWakeup: wakeupRead
      )
      return .cancellation
    } catch let error as PublicFirehoseTailerError {
      switch error {
      case let .outdatedCursor(retainedFromSeq):
        try? await outbound.write(
          .binary(ByteBuffer(data: try FirehoseFrameEncoder.infoFrame(
            name: "OutdatedCursor",
            message: nil
          )))
        )
        lastSent = max(0, retainedFromSeq - 1)
      case .consumerTooSlow, .writeTooSlow:
        logger.warning("dropping slow public firehose consumer")
        try? await outbound.write(
          .binary(ByteBuffer(data: try FirehoseFrameEncoder.errorFrame(
            error: "ConsumerTooSlow",
            message: nil
          )))
        )
        try? await outbound.close(.normalClosure, reason: "ConsumerTooSlow")
        return .failure(.consumerTooSlow)
      }
    } catch {
      if Task.isCancelled || error is CancellationError {
        return .cancellation
      }
      logger.debug("public firehose tailer failed")
      return .failure(.tailerFailed)
    }
  }
  return .cancellation
}
